import torch
import torch.nn as nn

# EVOLVE-BLOCK-START
class SpiralClassifier(nn.Module):
    def __init__(self):
        super().__init__()
        self.fc1 = nn.Linear(2, 16)
        self.relu = nn.ReLU()
        self.fc2 = nn.Linear(16, 3)

    def forward(self, x):
        x = self.fc1(x)
        x = self.relu(x)
        x = self.fc2(x)
        return x

def build_model():
    """Return an nn.Module mapping (batch, 2) inputs to (batch, 3) logits."""
    return SpiralClassifier()


def build_optimizer(model):
    """Return a torch optimizer for the model's parameters."""
    return torch.optim.Adam(model.parameters(), lr=0.01)
